import json,collections
cards=json.load(open('cards.json'))
DISC={'Seneca','Marcus Aurelius','Epictetus','Musonius Rufus','Miyamoto Musashi','Musashi','Yamamoto Tsunetomo','Inazo Nitobe','David Goggins','Peter Attia','Matthew Walker','Theodore Roosevelt','Zeno of Citium','Cleanthes','Diogenes','Cato (via Plutarch)','Hierocles','Boethius','M. Scott Peck','Benjamin Franklin','Juvenal','Ovid','Virgil','Robin Sharma','Hal Elrod','Arnold Bennett','Homer','Takuan Sōhō','Ikigai (García & Miralles)','Jordan Peterson','Florence Nightingale','Viktor Frankl'}
out=[]
for i,c in enumerate(cards):
  stat='wealth' if c['cat']=='Business' else ('discipline' if c['author'] in DISC else 'wisdom')
  out.append([c['cat'][0],{'wealth':'m','discipline':'d','wisdom':'w'}[stat],c['author'],c['book'],c['text'],c['q'],c['a'],c['action']])
js="// Generated by content/build_cards.py — %d cards. Fields: cat(L/B), stat(w/d/W), author, book, insight, question, answer, action\nconst RAW_CARDS=%s;\nconst CARDS=RAW_CARDS.map((c,i)=>({id:'c'+(i+1),cat:c[0]==='B'?'Business':'Life',stat:{m:'wealth',d:'discipline',w:'wisdom'}[c[1]],author:c[2],book:c[3],text:c[4],q:c[5],a:c[6],action:c[7]}));\n"%(len(out),json.dumps(out,ensure_ascii=False,separators=(',',':')))
# encode stat letters: wealth->w, discipline->d, wisdom->W
open('../cards.js','w').write(js.replace(json.dumps([],),'[]'))
# report
cat=collections.Counter(c['cat'] for c in cards);st=collections.Counter(r[1] for r in out)
book=collections.Counter((c['cat'],c['author'],c['book']) for c in cards)
with open('COUNTS.md','w') as f:
  f.write(f"# Card counts\nTotal: {len(cards)}\n\nBy category: {dict(cat)}\n\nBy stat letter (m=wealth,d=discipline,w=wisdom): {dict(st)}\n\n| Cat | Author | Book | Cards |\n|---|---|---|---|\n")
  for (ct,a,b),n in sorted(book.items(),key=lambda x:(x[0][0],-x[1],x[0][1])): f.write(f"| {ct} | {a} | {b} | {n} |\n")
print(len(cards),cat,st,len(book))
